		public void ImportDate()
        {
			string Operator=Scripter.GetParameterValue("Operator");
			string OrderName=Scripter.GetParameterValue("OrderName");
			string Productid=Scripter.GetParameterValue("ProductId");
			string gWeight=Scripter.GetParameterValue("gWeight");
			string I_OrBitUserId=Scripter.OrBitUserId;
			string I_OrBitUserName=Scripter.OrBitUserName;
			string I_ResourceId=Scripter.ResourceId;
			string I_ResourceName=Scripter.ResourceName;
			string returnMessage="";
			string ExceptionFieldName="";
			string FGQTY="";
			DataSet dss=null;

			if	(ScanLotSn.Length>0)
			{
				string str=@"DECLARE @return_value int,
							@FGQTY decimal(18,2)=0,
							@I_ExceptionFieldName nvarchar(100),
							@I_ReturnMessage nvarchar(max)					
				EXEC @return_value = [dbo].[Txn_DCFGWeightCollect]
					@I_ReturnMessage = @I_ReturnMessage output ,
					@I_ExceptionFieldName=@I_ExceptionFieldName output ,
					@FGQTY=@FGQTY output,
					@I_OrBitUserId = N'"+I_OrBitUserId+@"',
					@I_OrBitUserName = N'"+I_OrBitUserName+@"',
					@I_ResourceId = N'"+I_ResourceId+@"',
					@I_ResourceName = N'"+I_ResourceName+@"',
					@Operator=N'"+Operator+@"',
					@ScanLotSn=N'"+ScanLotSn+@"',
					@OrderName=N'"+OrderName+@"',
					@Productid=N'"+Productid+@"',
					@gWeight=N'"+gWeight+@"'
			
				select @I_ReturnMessage as N'I_ReturnMessage',
				@I_ExceptionFieldName as N'I_ExceptionFieldName',
				@return_value as N'return_value',
				@FGQTY as N'FGQTY'";				

				//执行 SQL 语句
				try
				{
					dss=Scripter.GetSqlDataSet(str);
				}
				catch (Exception ex)
	            {
					throw new Exception("保存数据出错!"+ex.Message);	
					return;
	            }
				
				ExceptionFieldName=Convert.ToString(dss.Tables[0].Rows[0]["I_ExceptionFieldName"]);
				returnMessage=Convert.ToString(dss.Tables[0].Rows[0]["I_ReturnMessage"]);
				FGQTY = Convert.ToString(dss.Tables[0].Rows[0]["FGQTY"]);
				
				if(Convert.ToString(dss.Tables[0].Rows[0]["return_value"])=="-1")
				{
					Scripter.SetParameterValue("WarnImage","error.png");
					Scripter.ShowMessage("返回错误:"+returnMessage,true);
				}
				else if(Convert.ToString(dss.Tables[0].Rows[0]["return_value"])=="-2")
				{
					Scripter.SetParameterValue("WarnImage","error.png");
					Scripter.ShowMessage(returnMessage,true);
				}
				else
				{
					if (CDt.Rows.Count>=5)
					{
						CDt.Clear();
						CDt.AcceptChanges();
					}
					tRow=null;
					tRow=CDt.NewRow();
					tRow["CurTime"]=System.DateTime.Now.ToLongTimeString().ToString();
					tRow["ScanSn"]=ScanLotSn;
					tRow["WeightQTY"]=gWeight;
					CDt.Rows.Add(tRow);	
					Scripter.SetParameterDataSet("ListValue",CDs);
					Scripter.SetParameterValue("WarnImage","ok.png");
					Scripter.ShowMessage(returnMessage,false);
					//--统计已经扫描的数量--
					Scripter.SetParameterValue("FGQTY",FGQTY);
					//--工装推送开关--
					Scripter.SetParameterValue("DC FGWeightSetting Test.IsMove","Y");
					Application.DoEvents();
					Thread.Sleep(50);
					
					IsPushBox= Scripter.GetParameterValue("pushBox");
					
//					Thread t = new Thread(new ThreadStart(pushBox));
//					t.Start();
					if (IsPushBox=="True") //看是否需要推箱子
					{
						IsPushBox ="";
						try
	    				{
							if(!Scripter.RS232Object.IsOpen)
							{
								Scripter.RS232Object.Close();
								Scripter.RS232Object.Open();
							}
							Scripter.RS232Object.RtsEnable=true;
							Thread.Sleep(200);
							Scripter.RS232Object.RtsEnable=false;
						}
						catch (Exception ex)
			            {
							throw new Exception("发送移动操作出错!"+ex.Message);	
							return;
			            }
					}
				}
				if (ExceptionFieldName=="Operator")
				 Scripter.SetControlFocus("Operator");
				else if (ExceptionFieldName=="OrderName")
				 Scripter.SetControlFocus("OrderName");
				else
				  Scripter.SetControlFocus("ScanLotSn");
			}
			Scripter.SetParameterValue("ScanLotSn","");
			Scripter.SetParameterValue("gWeight","0");
			Scripter.SetControlFocus("ScanLotSn");
			ResetRS232();//重置端口
		}
		
		private void ResetRS232()
		{
			killTime = DateTime.Now - StartTime;
			if (killTime.TotalMinutes>10*ExecInterval)
			{
				ExecInterval++;			
				Scripter.RS232Object.Close();
				Thread.Sleep(100);
				Scripter.RS232Object.Dispose();
				Thread.Sleep(100);
				Scripter.RS232Object.Open();
				if(Scripter.RS232Object.IsOpen)
				{
					Scripter.ShowMessage("重新开启串口成功!",true);	
				}
			}
		}
		//端口 接收事件
	    public void RSDataReceived(object sender, SerialDataReceivedEventArgs e)
        {	
			decimal ReceiveDec=0;
			try
            {
				if (!Scripter.RS232Object.IsOpen)
				{
					Scripter.ShowMessage("串口没有打开！" ,true);		
					return;
				}
				
				if (IsProcess)	//正在处理就返回
					return;

				
				int ByteLen=Scripter.RS232Object.BytesToRead;
                if ( ByteLen>0)
                {
					 ReceiveStr ="";
					 ReceiveStr = Scripter.RS232Object.ReadLine();
					 Scripter.RS232Object.DiscardOutBuffer();
					 Scripter.RS232Object.DiscardInBuffer();			
                    if (ReceiveStr != "")
                    {
						Scripter.SetParameterValue("DC FGWeightSetting Test.gWeight",ReceiveStr);
						ReceiveStr=ReceiveStr.Replace("g","").Replace("+","").Replace("\n","").Trim();
									
						//判断是否需要传称重数据

						isNumberic(ReceiveStr,out ReceiveDec);
						if (ReceiveDec>5)		//减少震动,把重量小于5g的排除
						{	
							Scripter.SetParameterValue("gWeight",ReceiveStr.Trim());
							
							if (IsScan)	//判断是否扫描条码
							{
								IsProcess = true;
								IsScan=false;
								ScanLotSn="";
								ScanLotSn=Scripter.GetParameterValue("ScanLotSn");
								ImportDate();
							}
						}
						IsProcess = false;
					}
				}
			}	
            catch (Exception ex)
            {
				IsProcess = false;
				Scripter.ShowMessage("从COM口接收数据异常!"+ex.Message ,true);			
            }
        }
		
