		}
		
		public bool OpenPort(string PortName)
		{
			try{
				Scripter.RS232Object =new SerialPort(PortName,9600,Parity.None ,8,StopBits.One);
				Scripter.RS232Object.ReadBufferSize=4096;
				Scripter.RS232Object.DataReceived += new SerialDataReceivedEventHandler(RSDataReceived);//定义串口接收事件
				 if (Scripter.RS232Object.IsOpen==true)
				{
					Scripter.RS232Object.Close();
					Scripter.RS232Object.Dispose();
				}
				Scripter.RS232Object.Open();
				if(Scripter.RS232Object.IsOpen)
				{
					return true;
				}
				else
				{
					return false;
				}
			  }
			catch(IOException ex)
			{
				MessageBox.Show(ex.Message);
				return false;
			}
		}
