	//从服务器取得端口参数
		public DataSet getPortSetting()
		{			
			string I_OrBitUserId=Scripter.OrBitUserId;
			string I_OrBitUserName=Scripter.OrBitUserName;
			string I_ResourceId=Scripter.ResourceId;
			string I_ResourceName=Scripter.ResourceName;
			string returnMessage="";
			string ExceptionFieldName="";
			string str=@"DECLARE @return_value int,
							@FGWeightMax decimal(18,2)=0,
							@FGWeightMin decimal(18,2)=0,
							@Port nvarchar(50)='',
							@I_ExceptionFieldName nvarchar(100),
							@I_ReturnMessage nvarchar(max)					
				EXEC @return_value = [dbo].[Txn_PortSettingGet]
					@I_ReturnMessage = @I_ReturnMessage output ,
					@I_ExceptionFieldName=@I_ExceptionFieldName output ,
					@FGWeightMax=@FGWeightMax output,
					@FGWeightMin=@FGWeightMin output,
					@Port=@Port output,
					@I_OrBitUserId = N'"+I_OrBitUserId+@"',
					@I_OrBitUserName = N'"+I_OrBitUserName+@"',
					@I_ResourceId = N'"+I_ResourceId+@"',
					@I_ResourceName = N'"+I_ResourceName+@"'
			
				select @I_ReturnMessage as N'I_ReturnMessage',
				@I_ExceptionFieldName as N'I_ExceptionFieldName',
				@return_value as N'return_value',
				@Port as N'Port',
				@FGWeightMin as N'FGWeightMin',
				@FGWeightMax as N'FGWeightMax'";
				DataSet dss=Scripter.GetSqlDataSet(str);
			return dss;
		}
		//保存端口参数到服务器
		public void SavePortSetting()
		{			
			string I_OrBitUserId=Scripter.OrBitUserId;
			string I_OrBitUserName=Scripter.OrBitUserName;
			string I_ResourceId=Scripter.ResourceId;
